<?php require 'config/database.php'; $pageTitle='Courses'; if(isset($_GET['delete'])){$q=$pdo->prepare('DELETE FROM courses WHERE id=?');$q->execute([(int)$_GET['delete']]);header('Location: courses.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO courses(code,title,credit_hours,instructor) VALUES(?,?,?,?)');$q->execute([$_POST['code'],$_POST['title'],(int)$_POST['credit_hours'],$_POST['instructor']]);header('Location: courses.php');exit;} $rows=$pdo->query('SELECT * FROM courses ORDER BY id DESC')->fetchAll(); require 'includes/header.php'; ?>
<h2>Courses</h2><div class="row g-4"><div class="col-md-4"><div class="card shadow-sm p-3"><h5>Add Course</h5><form method="post"><input required class="form-control mb-2" name="code" placeholder="Course code"><input required class="form-control mb-2" name="title" placeholder="Title"><input required class="form-control mb-2" type="number" name="credit_hours" placeholder="Credit hours"><input required class="form-control mb-2" name="instructor" placeholder="Instructor"><button class="btn btn-primary w-100">Add</button></form></div></div><div class="col-md-8"><div class="card shadow-sm"><table class="table"><thead><tr><th>Code</th><th>Title</th><th>Credits</th><th>Instructor</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['code']?></td><td><?=$r['title']?></td><td><?=$r['credit_hours']?></td><td><?=$r['instructor']?></td><td><a data-confirm-delete class="btn btn-sm btn-danger" href="courses.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require 'includes/footer.php'; ?>
